import{c as e,Q as s,j as r,m as a}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"Thariq：Dynamic Workflows 是 Claude Code 自 Skills/Subagents 以來最大升級（含深度實戰）","description":"","frontmatter":{"url":"https://x.com/trq212/status/2061907538741006796","title":"Thariq：Dynamic Workflows 是 Claude Code 自 Skills/Subagents 以來最大升級（含深度實戰）","author":"Thariq","archived":"2026-06-15T00:00:00.000Z","handle":"@trq212","published":"2026-06-02T00:00:00.000Z","score":"8.3/10","stats":"4,694 likes · 364 retweets","tags":["dynamic-workflows","best-practices","non-technical","deep-dive","practical-guide"],"type":"tweet"},"headers":[],"relativePath":"research/tweets/2026-06-02-@trq212-006796.md","filePath":"research/tweets/2026-06-02-@trq212-006796.md","lastUpdated":1785909234000}'),o={name:"research/tweets/2026-06-02-@trq212-006796.md"};function i(d,t,n,l,c,h){return s(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="thariq-dynamic-workflows-是-claude-code-自-skills-subagents-以來最大升級-含深度實戰" tabindex="-1">Thariq：Dynamic Workflows 是 Claude Code 自 Skills/Subagents 以來最大升級（含深度實戰） <a class="header-anchor" href="#thariq-dynamic-workflows-是-claude-code-自-skills-subagents-以來最大升級-含深度實戰" aria-label="Permalink to &quot;Thariq：Dynamic Workflows 是 Claude Code 自 Skills/Subagents 以來最大升級（含深度實戰）&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/trq212/status/2061907538741006796" target="_blank" rel="noreferrer">https://x.com/trq212/status/2061907538741006796</a><strong>作者</strong>：Thariq（@trq212） <strong>發布日期</strong>：2026-06-02 <strong>收錄日期</strong>：2026-06-15 <strong>類型</strong>：tweet <strong>統計</strong>：4,694 likes · 364 retweets</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>Workflows are the biggest upgrade to Claude Code&#39;s capabilities since skills and subagents.</p><p>I dove deep into it with @sidbid to figure out best practices, examples and more. I&#39;m particularly excited about the non-technical tasks it enables for Claude Code.</p><p>Key findings after deep dive:</p><p>→ Workflows are NOT just for code. They&#39;re transformative for knowledge work: research synthesis, document analysis, content pipelines.</p><p>→ Best pattern: Haiku workers + Opus/Sonnet synthesizer. Keeps costs sane while scaling horizontally.</p><p>→ Scope binding is everything. &quot;Audit my codebase&quot; = expensive. &quot;Audit the 20 files in /src/api&quot; = precise and affordable.</p><p>→ The workflow JS file is the deliverable. Save it. Version it. Reuse it.</p><p>→ Non-technical workflows that now make sense: PR analysis across 50 files, competitor monitoring across 30 sources, customer feedback synthesis.</p><p>Full deep dive article in thread below 👇</p><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>9/10</td><td>Haiku workers + Opus synthesizer 模式、scope binding 原則直接可套用</td></tr><tr><td>B. 創新性 (20%)</td><td>8/10</td><td>非技術工作流用例（PR分析、競品監控）是重要新洞見</td></tr><tr><td>C. 證據品質 (20%)</td><td>7/10</td><td>深度研究成果有具體模式但缺量化數據</td></tr><tr><td>D. 技術深度 (15%)</td><td>8/10</td><td>涵蓋成本結構和 scope binding 等重要實作原則</td></tr><tr><td>E. 泛化性 (15%)</td><td>9/10</td><td>非技術用例大幅擴展了工具的適用邊界</td></tr><tr><td><strong>加權總分</strong></td><td><strong>8.3/10</strong></td><td>A×0.3+B×0.2+C×0.2+D×0.15+E×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：SKILL <strong>理由</strong>：非技術工作流用例清單和 Haiku/Opus 分工模式適合整合進 dynamic-workflows SKILL 的最佳實踐章節。</p>',17)])])}const g=e(o,[["render",i]]);export{u as __pageData,g as default};
